INSERT INTO `faqs` (`id`, `intent`, `question`, `answer`, `language`, `active`, `created_at`) VALUES
(1, 'general_contact', 'How can I contact the authority?', 'For general inquiries, please call the Road Passenger Transport Authority on the official contact number published on this website. / සාමාන්‍ය විමසීම් සඳහා මෙම වෙබ් අඩවියේ දක්වා ඇති නිල දුරකථන අංකයට අමතන්න.', 'en', 1, '2026-09-28 14:58:35'),
(2, 'general_contact', 'What is the contact number?', 'For general inquiries, please call the Road Passenger Transport Authority on the official contact number published on this website. / සාමාන්‍ය විමසීම් සඳහා මෙම වෙබ් අඩවියේ දක්වා ඇති නිල දුරකථන අංකයට අමතන්න.', 'en', 1, '2026-09-28 14:58:35'),
(3, 'general_contact', 'Who can I call for help?', 'For general inquiries, please call the Road Passenger Transport Authority on the official contact number published on this website. / සාමාන්‍ය විමසීම් සඳහා මෙම වෙබ් අඩවියේ දක්වා ඇති නිල දුරකථන අංකයට අමතන්න.', 'en', 1, '2026-09-28 14:58:35'),
(4, 'general_contact', 'Where can I get general assistance?', 'For general inquiries, please call the Road Passenger Transport Authority on the official contact number published on this website. / සාමාන්‍ය විමසීම් සඳහා මෙම වෙබ් අඩවියේ දක්වා ඇති නිල දුරකථන අංකයට අමතන්න.', 'en', 1, '2026-09-28 14:58:35'),
